<?php
require __DIR__.'/../includes/modules.php';$user=require_role('admin');$error='';$month=is_string($_GET['month']??null)?$_GET['month']:date('Y-m');$d=DateTime::createFromFormat('!Y-m',$month);if(!$d||$d->format('Y-m')!==$month){$error='Enter a valid report month.';$month=date('Y-m');}$start=$month.'-01';$end=date('Y-m-t',strtotime($start));
$rows=query_rows("SELECT u.employee_code,u.full_name,u.department,
(SELECT COUNT(*) FROM attendance a WHERE a.employee_id=u.id AND a.attendance_date BETWEEN ? AND ? AND a.status='Present') AS present_days,
(SELECT COUNT(*) FROM attendance a WHERE a.employee_id=u.id AND a.attendance_date BETWEEN ? AND ? AND a.status='Absent') AS absent_days,
(SELECT COUNT(*) FROM attendance a WHERE a.employee_id=u.id AND a.attendance_date BETWEEN ? AND ? AND a.status='Late') AS late_days,
(SELECT COUNT(*) FROM attendance a WHERE a.employee_id=u.id AND a.attendance_date BETWEEN ? AND ? AND a.status='Half Day') AS half_days,
(SELECT COUNT(*) FROM attendance a WHERE a.employee_id=u.id AND a.attendance_date BETWEEN ? AND ? AND a.status='Week Off') AS week_off_days,
(SELECT COUNT(*) FROM attendance a WHERE a.employee_id=u.id AND a.attendance_date BETWEEN ? AND ? AND a.status='Leave') AS leave_days,
(SELECT COUNT(*) FROM leave_requests l WHERE l.employee_id=u.id AND l.status='Approved' AND l.start_date<=? AND l.end_date>=?) AS approved_requests,
COALESCE((SELECT SUM(s.net_salary) FROM salaries s WHERE s.employee_id=u.id AND s.salary_month=?),0) AS net_salary,
COALESCE((SELECT SUM(s.net_salary) FROM salaries s WHERE s.employee_id=u.id AND s.salary_month=? AND s.payment_status='Paid'),0) AS paid_salary
FROM users u WHERE role='employee' ORDER BY full_name",[$start,$end,$start,$end,$start,$end,$start,$end,$start,$end,$start,$end,$end,$start,$start,$start]);
if(($_GET['export']??'')==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="ems-report-'.$month.'.csv"');$out=fopen('php://output','w');fputcsv($out,['Employee ID','Name','Department','Present','Absent','Late','Half days','Week off','Leave days','Approved requests overlapping month','Net salary (INR)','Paid salary (INR)']);foreach($rows as $r){foreach($r as &$v)if(is_string($v)&&preg_match('/^[=+@\-\t\r\n]/',$v))$v="'".$v;unset($v);fputcsv($out,array_values($r));}fclose($out);exit;}
page_start('Reports',$user);error_notice($error);?><section class="card"><form method="get"><div class="actions"><?php input_field('month','Report month',$month,'month');?><button class="btn btn-primary">View Report</button><button class="btn btn-secondary" name="export" value="csv">Download CSV</button></div></form><p>Attendance counts use recorded days. Approved leave counts include requests overlapping the selected month. Salary values are in INR.</p><div class="table-container"><table class="table"><thead><tr><?php foreach(['ID','Name','Department','Present','Absent','Late','Half days','Week off','Leave days','Approved leave requests','Net salary','Paid salary'] as $label):?><th><?=h($label)?></th><?php endforeach;?></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php foreach($r as $key=>$v):?><td><?=in_array($key,['net_salary','paid_salary'],true)?money($v):h($v)?></td><?php endforeach;?></tr><?php endforeach;if(!$rows)echo '<tr><td colspan="12">No employees found.</td></tr>';?></tbody></table></div></section><?php page_end();
